def transform(grid):
    h, w = len(grid), len(grid[0])
    g = [row[:] for row in grid]
    bg = max(range(10), key=lambda c: sum(v == c for row in g for v in row))

    # Find the colored bars on the top and bottom edges.
    def edge_run(row):
        vals = [(j, row[j]) for j in range(w) if row[j] != bg]
        if not vals:
            return None
        color = vals[0][1]
        cols = [j for j, c in vals if c == color]
        return color, min(cols), max(cols)

    top = edge_run(g[0])
    bottom = edge_run(g[-1])
    bars = [b for b in (top, bottom) if b]
    bar_color = bars[0][0] if bars else bg

    points = [(r, c, g[r][c]) for r in range(h) for c in range(w)
              if g[r][c] != bg and g[r][c] != bar_color]
    if not points or not top or not bottom:
        return g

    k = len(points)
    dot_color = points[0][2]

    def selected_cols(bar):
        _, lo, hi = bar
        return list(range(max(lo, hi - k + 1), hi + 1))

    tcols = selected_cols(top)
    bcols = selected_cols(bottom)
    active = set(c for _, c, _ in points)
    active_top = bool(active.intersection(tcols))
    active_bottom = bool(active.intersection(bcols))

    # Fill the beam from the bar without points all the way across.
    for cols, is_active, from_top in (
        (tcols, active_top, True),
        (bcols, active_bottom, False),
    ):
        if not is_active:
            for r in range(h):
                for c in cols:
                    if g[r][c] == bg:
                        g[r][c] = dot_color

    # On the beam containing points, fill from its edge up to each point.
    for r, c, _ in points:
        if c in tcols:
            for rr in range(1, r + 1):
                if g[rr][c] == bg:
                    g[rr][c] = dot_color
            g[r][c] = 4
        elif c in bcols:
            for rr in range(r, h - 1):
                if g[rr][c] == bg:
                    g[rr][c] = dot_color
            g[r][c] = 4

    return g
